def solve_versions(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    best = None
    best_vector = None

    def search(selected, bounds, pending, graph):
        nonlocal best, best_vector

        bounds = dict(bounds)
        while pending:
            name, low, high = pending.pop()
            if name in bounds:
                old_low, old_high = bounds[name]
                low = max(low, old_low)
                high = min(high, old_high)
            if low > high:
                return
            bounds[name] = (low, high)
            if name in selected and not (low <= selected[name] <= high):
                return

        unresolved = [name for name in bounds if name not in selected]
        if not unresolved:
            if not _is_acyclic(graph):
                return
            vector = tuple(selected.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best = dict(selected)
                best_vector = vector
            return

        name = min(unresolved)
        low, high = bounds[name]

        for row in packages.get(name, []):
            version = row['version']
            if not (low <= version <= high):
                continue
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue

            active_deps = []
            for dep in row['deps']:
